ALLOWED_ORIGINS = {"https://cristoxd73.github.io"}
ALLOWED_ORIGINS.update(o.strip() for o in os.environ.get("STUDIO_LINK_ORIGINS", "").split(",")
                       if ORIGIN_SHAPE.match(o.strip()))
